{
  repository(owner: "pawtograder", name: "platform") {
    pullRequest(number: 831) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          path
          line
          comments(first: 10) {
            nodes {
              databaseId
              author { login }
              body
            }
          }
        }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved == false) | {threadId: .id, path: .path, line: .line, comments: [.comments.nodes[] | {id: .databaseId, author: .author.login, body: .body}]}' > /tmp/unresolved.json 2>&1
cat /tmp/unresolved.json | python3 -c "import json,sys
for line in sys.stdin:
    t=json.loads(line)
    print('='*80)
    print('THREAD:', t['threadId'])
    print('PATH:', t['path'], 'LINE:', t['line'])
    for c in t['comments']:
        print('--- @%s (comment id %s) ---' % (c['author'], c['id']))
        print(c['body'])
        print()
"

