7	const rateLimitStore = new Map<string, number[]>();
8	const RATE_LIMIT_MAX_REQUESTS = 3;
9	const RATE_LIMIT_WINDOW_MS = 60 * 1000; // 1 minute
10	
11	function cleanupOldEntries(timestamps: number[], currentTime: number): number[] {
12	  return timestamps.filter((timestamp) => currentTime - timestamp < RATE_LIMIT_WINDOW_MS);
13	}
14	
15	function checkRateLimit(orgName: string, repoName: string, path: string): void {
16	  const fileKey = `${orgName}/${repoName}:${path}`;
17	  const currentTime = Date.now();
18	
19	  // Get existing timestamps for this file
20	  let timestamps = rateLimitStore.get(fileKey) || [];
21	
22	  // Clean up old entries
23	  timestamps = cleanupOldEntries(timestamps, currentTime);
24	
25	  // Check if rate limit is exceeded
26	  if (timestamps.length >= RATE_LIMIT_MAX_REQUESTS) {
27	    throw new Error(
28	      `Rate limit exceeded: File ${path} in ${orgName}/${repoName} has been requested ${RATE_LIMIT_MAX_REQUESTS} times within the last minute. Please wait before trying again.`
29	    );
30	  }
31	
32	  // Add current timestamp
33	  timestamps.push(currentTime);
34	  rateLimitStore.set(fileKey, timestamps);
35	
36	  // Cleanup old entries from the store periodically
37	  if (Math.random() < 0.1) {
38	    // 10% chance to clean up on each request
39	    for (const [key, ts] of rateLimitStore.entries()) {
40	      const cleanedTs = cleanupOldEntries(ts, currentTime);
41	      if (cleanedTs.length === 0) {
42	        rateLimitStore.delete(key);
43	      } else {
44	        rateLimitStore.set(key, cleanedTs);
45	      }
46	    }
47	  }
48	}
49	
50	async function handleRequest(req: Request, scope: Sentry.Scope) {
51	  const { courseId, orgName, repoName, path, skipRetryOnNotFound } = (await req.json()) as FunctionTypes.GetFileRequest;
52	  scope?.setTag("function", "repository-get-file");
53	  scope?.setTag("courseId", courseId.toString());
54	  scope?.setTag("orgName", orgName);
55	  scope?.setTag("repoName", repoName);
56	  scope?.setTag("path", path);
57	  const { supabase } = await assertUserIsInstructor(courseId, req.headers.get("Authorization")!);
58	  const courseOrgName = await supabase.from("classes").select("github_org").eq("id", courseId).single();
59	  // Surface a real (retryable) lookup failure instead of a misleading "...associated with
60	  // undefined" error when `data` is null.
61	  if (courseOrgName.error) {
62	    throw new Error(`Could not look up the GitHub org for course ${courseId}: ${courseOrgName.error.message}`);
63	  }
64	  if (courseOrgName.data?.github_org != orgName && orgName != "pawtograder") {
65	    throw new Error(
66	      `Requested a file from ${orgName}/${repoName} but the course is associated with ${courseOrgName.data?.github_org}`
67	    );
68	  }
69	
70	  // Check rate limit before making the GitHub API call
71	  checkRateLimit(orgName, repoName, path);
72	
73	  try {
74	    return await github.getFileFromRepo(orgName + "/" + repoName, path);
75	  } catch (error) {
76	    scope?.setTag("get_file_error", JSON.stringify(error));
77	    if (error && typeof error === "object" && "status" in error && (error as { status: number }).status === 404) {
78	      scope?.setTag("get_file_error_status", (error as { status: number }).status.toString());
79	      // The editor's read path opens files that may legitimately not exist yet (create-on-save),
80	      // so it sets skipRetryOnNotFound to avoid the 15s+retry that otherwise stalls the UI for
81	      // 15-30s. Other callers (racing fresh repo creation) keep the delayed retry.
82	      if (skipRetryOnNotFound) {
83	        throw new NotFoundError(`File ${path} not found in ${orgName}/${repoName}`);
84	      }
85	      // Add a delay to help clients get over racing with repo creation
86	      await new Promise((resolve) => setTimeout(resolve, 15000));
87	
88	      // Retry the request once after the delay
89	      try {
90	        return await github.getFileFromRepo(orgName + "/" + repoName, path);
91	      } catch (retryError) {
92	        if (
93	          retryError &&
94	          typeof retryError === "object" &&
95	          "status" in retryError &&
96	          (retryError as { status: number }).status === 404
97	        ) {
98	          scope?.setTag("get_file_retry_error", JSON.stringify(retryError));
99	          throw new NotFoundError(`File ${path} not found in ${orgName}/${repoName}`);
100	        }
101	        throw retryError;
102	      }
103	    }
104	    throw error;
105	  }
106	}
107	
108	Deno.serve(async (req) => {
109	  return await wrapRequestHandler(req, handleRequest);
110	});

